package com.hayame.app.core

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager
import androidx.annotation.DrawableRes
import com.hayame.app.R

/**
 * The two launcher icons the user can pick in Settings > Appearance.
 *
 * Each maps to an `activity-alias` in the manifest that targets MainActivity. Exactly one alias is
 * enabled at a time, which is how Android swaps a launcher icon without reinstalling. The assets
 * are generated by `design/icons/make-icons.swift`, so they match iOS.
 */
enum class HayameAppIcon(
    val title: String,
    val subtitle: String,
    val aliasClassName: String,
    @DrawableRes val previewRes: Int,
) {
    LOGO("Logo", "The Hayame car mark", "com.hayame.app.LauncherLogo", R.drawable.app_icon_preview_logo),
    NAME("Name", "The HAYAME wordmark", "com.hayame.app.LauncherWordmark", R.drawable.app_icon_preview_wordmark),
}

object AppIconManager {
    private const val PREFS = "hayame_app_icon"
    private const val KEY_SELECTED = "selected"

    fun current(context: Context): HayameAppIcon {
        val stored = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getString(KEY_SELECTED, null)
        stored?.let { name -> HayameAppIcon.entries.firstOrNull { it.name == name } }?.let { return it }
        // No stored choice yet: trust whichever alias the package manager has enabled.
        val pm = context.packageManager
        val wordmark = ComponentName(context, HayameAppIcon.NAME.aliasClassName)
        return if (pm.getComponentEnabledSetting(wordmark) == PackageManager.COMPONENT_ENABLED_STATE_ENABLED) {
            HayameAppIcon.NAME
        } else {
            HayameAppIcon.LOGO
        }
    }

    /**
     * Enables the alias for [icon] and disables the others. The launcher picks the change up on
     * its own; some launchers rebuild the home-screen shortcut when they do.
     */
    fun select(context: Context, icon: HayameAppIcon) {
        val pm = context.packageManager
        // Enable the new alias first so there is never a moment with no launcher entry.
        pm.setComponentEnabledSetting(
            ComponentName(context, icon.aliasClassName),
            PackageManager.COMPONENT_ENABLED_STATE_ENABLED,
            PackageManager.DONT_KILL_APP,
        )
        HayameAppIcon.entries.filter { it != icon }.forEach { other ->
            pm.setComponentEnabledSetting(
                ComponentName(context, other.aliasClassName),
                PackageManager.COMPONENT_ENABLED_STATE_DISABLED,
                PackageManager.DONT_KILL_APP,
            )
        }
        context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
            .edit()
            .putString(KEY_SELECTED, icon.name)
            .apply()
    }
}
